import{_ as s,C as e,c,o as l,a9 as r,G as n}from"./chunks/framework.BMko4Wr3.js";const g=JSON.parse('{"title":"兼容性","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/ExcellentEnchants"},{"title":"兼容性","link":"/ExcellentEnchants/features.compatibility"}]},"headers":[],"relativePath":"ExcellentEnchants/features.compatibility.md","filePath":"ExcellentEnchants/features.compatibility.md"}'),i={name:"ExcellentEnchants/features.compatibility.md"};function p(d,t,m,_,h,u){const o=e("NolebaseGitContributors"),a=e("NolebaseGitChangelog");return l(),c("div",null,[t[0]||(t[0]=r('<h1 id="兼容性" tabindex="-1">兼容性 <a class="header-anchor" href="#兼容性" aria-label="Permalink to &quot;兼容性&quot;">​</a></h1><p>ExcellentEnchants 以<strong>数据驱动</strong>的附魔与<strong>无感</strong>集成至服务器为特色，所有新增附魔都在原版命令、其他插件和<strong>没有兼容性补丁的</strong> Spigot/Paper API 中“可见”。</p><p>与其他自定义附魔插件不同的是，ExcellentEnchants 的附魔<strong>原生支持所有</strong>原版机制，如附魔台、铁砧、村民交易、钓鱼、战利品表等。因此它没有硬编码的补丁。</p><div class="danger custom-block"><p class="custom-block-title">危险</p><p><strong>不要</strong>尝试在卸载 ExcellentEnchants 后运行服务器，否则所有物品会永久丢失新附魔。</p></div><h2 id="命名空间" tabindex="-1">命名空间 <a class="header-anchor" href="#命名空间" aria-label="Permalink to &quot;命名空间&quot;">​</a></h2><p>默认情况下新附魔的注册命名空间为 <code>excellentenchants</code>。</p><p>若要在命令和其他插件的配置中使用 <strong>ExcellentEnchants</strong> 的附魔，你需要按 <code>命名空间:附魔名称</code> 的格式填写 —— 例如 <code>excellentenchants:tunnel</code>。</p><div class="warning custom-block"><p class="custom-block-title">警告</p><p>如果你不能使用自定义命名空间，你可以在 <code>distribution.yml</code> 配置文件中强制其使用原版的 <code>minecraft</code> 命名空间。</p><p><em><strong>这个选项不稳定，可能会引发潜在的问题。</strong></em></p></div>',8)),n(o),n(a)])}const E=s(i,[["render",p]]);export{g as __pageData,E as default};
